function haversineM(lat1,lon1,lat2,lon2){const rad=x=>x*Math.PI/180,R=6371008.8,dlat=rad(lat2-lat1),dlon=rad(lon2-lon1),a=Math.sin(dlat/2)**2+Math.cos(rad(lat1))*Math.cos(rad(lat2))*Math.sin(dlon/2)**2;return 2*R*Math.asin(Math.min(1,Math.sqrt(a)))}
