function drawGeo(distance,bearing){const c=$('geoVectorCanvas');if(!c)return;const x=c.getContext('2d'),w=c.width,h=c.height;x.clearRect(0,0,w,h);const g=x.createLinearGradient(0,0,w,h);g.addColorStop(0,'#081d2d');g.addColorStop(1,'#06111b');x.fillStyle=g;x.fillRect(0,0,w,h);x.strokeStyle='#17394c';for(let i=1;i<8;i++){x.beginPath();x.moveTo(i*w/8,0);x.lineTo(i*w/8,h);x.stroke()}for(let i=1;i<5;i++){x.beginPath();x.moveTo(0,i*h/5);x.lineTo(w,i*h/5);x.stroke()}const cx=w*.5,cy=h*.55,angle=(bearing||0)*Math.PI/180,len=Math.min(w*.34,Math.max(35,Math.log10(Math.max(distance||0,0)+1)*65)),ex=cx+Math.sin(angle)*len,ey=cy-Math.cos(angle)*len;x.strokeStyle='#2f9bb9';x.fillStyle='#44e2ee';x.lineWidth=2;x.beginPath();x.arc(cx,cy,9,0,Math.PI*2);x.fill();x.stroke();x.strokeStyle='#44e2ee';x.lineWidth=4;x.shadowColor='#44e2ee';x.shadowBlur=12;x.beginPath();x.moveTo(cx,cy);x.lineTo(ex,ey);x.stroke();x.beginPath();x.moveTo(ex,ey);x.lineTo(ex-10*Math.cos(angle-.45),ey-10*Math.sin(angle-.45));x.moveTo(ex,ey);x.lineTo(ex-10*Math.cos(angle+.45),ey-10*Math.sin(angle+.45));x.stroke();x.shadowBlur=0;x.fillStyle='#e0f7ff';x.font='bold 15px system-ui';x.textAlign='center';x.fillText('Epoch B',ex,ey-15);x.fillStyle='#a8c4d7';x.fillText('Epoch A',cx,cy+28);x.textAlign='left';x.font='12px system-ui';x.fillText('Direction '+fmt(bearing,2)+'°',15,22);x.fillText('Line length is visually scaled, not a map scale',15,h-14)}
function calcGeo(){lastGeo=null;const a={lat:Number($('geoLatA').value),lon:Number($('geoLonA').value)},b={lat:Number($('geoLatB').value),lon:Number($('geoLonB').value)},years=Number($('geoYears').value),sigma=Number($('geoSigma').value);if(![a.lat,a.lon,b.lat,b.lon,years,sigma].every(Number.isFinite)||Math.abs(a.lat)>90||Math.abs(b.lat)>90||Math.abs(a.lon)>180||Math.abs(b.lon)>180||years<=0||sigma<0){['geoDistance','geoBearing','geoRate','geoRateSigma'].forEach(id=>{if($(id))$(id).textContent='—'});$('geoEquation').textContent='Calculation blocked by invalid input.';status('geoMessage','Invalid input. Latitude must be ±90°, longitude ±180°, duration positive, uncertainty non-negative.','bad');return}const d=haversineM(a.lat,a.lon,b.lat,b.lon),bearing=initialBearing(a.lat,a.lon,b.lat,b.lon),v=d*1000/years,sigRate=Math.sqrt(2)*sigma/years;lastGeo={epochA:a,epochB:b,durationYears:years,perEpochHorizontalSigmaMm:sigma,displacementM:d,azimuthDeg:bearing,rateMmPerYear:v,rateSigmaOneSigmaMmPerYear:sigRate,method:'Spherical haversine; independent equal epoch uncertainties; approximate local horizontal analysis',classification:'User-input calculation; not live GNSS telemetry',calculatedAt:new Date().toISOString()};$('geoDistance').textContent=d<1?fmt(d*1000,2)+' mm':fmt(d,4)+' m';$('geoBearing').textContent=fmt(bearing,2)+'°';$('geoRate').textContent=fmt(v,3)+' mm/year';$('geoRateSigma').textContent='±'+fmt(sigRate,3)+' mm/year';$('geoEquation').textContent='v = '+fmt(d,6)+' m / '+fmt(years,3)+' yr = '+fmt(v,3)+' mm/yr; σv = √(σA²+σB²)/Δt = '+fmt(sigRate,3)+' mm/yr';drawGeo(d,bearing);status('Calculation complete. Results describe the coordinate inputs only. Real tectonic motion requires reference-frame-corrected survey epochs, monument stability and formal uncertainty analysis.','good')}
