function drawEnergy(r){const c=$('enFlowCanvas');if(!c)return;const ctx=c.getContext('2d'),w=c.width,h=c.height;ctx.clearRect(0,0,w,h);ctx.fillStyle='#061421';ctx.fillRect(0,0,w,h);for(let i=0;i<12;i++){ctx.strokeStyle='rgba(56,124,154,.12)';ctx.beginPath();ctx.moveTo(i*w/12,0);ctx.lineTo(i*w/12,h);ctx.stroke()}const boxes=[{x:20,y:32,w:145,h:60,name:'SOLAR PV',val:fmt(r.pv,1)+' kWh/d',color:'#ffc66b'},{x:20,y:134,w:145,h:60,name:'WIND',val:fmt(r.wind,1)+' kWh/d',color:'#44e2ee'},{x:20,y:236,w:145,h:60,name:'MICRO-HYDRO',val:fmt(r.hydro,2)+' kWh/d',color:'#9a83ff'}];for(const b of boxes){ctx.fillStyle='#0b2234';ctx.strokeStyle=b.color;ctx.lineWidth=1.5;ctx.beginPath();ctx.roundRect(b.x,b.y,b.w,b.h,10);ctx.fill();ctx.stroke();ctx.fillStyle=b.color;ctx.font='bold 10px system-ui';ctx.fillText(b.name,b.x+12,b.y+21);ctx.fillStyle='#deeff8';ctx.font='bold 13px system-ui';ctx.fillText(b.val,b.x+12,b.y+44);ctx.beginPath();ctx.strokeStyle=b.color;ctx.lineWidth=2;ctx.moveTo(b.x+b.w,b.y+b.h/2);ctx.bezierCurveTo(230,b.y+b.h/2,220,175,295,175);ctx.stroke();for(let k=0;k<4;k++){const xx=b.x+b.w+((Date.now()/18+k*55)%115);ctx.fillStyle=b.color;ctx.globalAlpha=.35;ctx.beginPath();ctx.arc(xx,b.y+b.h/2,2.2,0,Math.PI*2);ctx.fill();ctx.globalAlpha=1}}
function node(x,y,w,h,title,sub,color){ctx.fillStyle='#0a1e2e';ctx.strokeStyle=color;ctx.lineWidth=2;ctx.beginPath();ctx.roundRect(x,y,w,h,12);ctx.fill();ctx.stroke();ctx.fillStyle=color;ctx.font='bold 12px system-ui';ctx.fillText(title,x+12,y+25);ctx.fillStyle='#a4c0d2';ctx.font='11px system-ui';ctx.fillText(sub,x+12,y+47)}node(295,140,170,74,'POWER CONVERSION','inverter / controller','#44e2ee');node(510,72,135,68,'BATTERY','storage scenario','#9a83ff');node(510,208,135,68,'LOAD','daily demand','#4de0ae');ctx.strokeStyle='#44e2ee';ctx.lineWidth=2;ctx.beginPath();ctx.moveTo(465,163);ctx.lineTo(510,106);ctx.moveTo(465,188);ctx.lineTo(510,237);ctx.stroke();ctx.fillStyle='#b6cfdf';ctx.font='10px system-ui';ctx.fillText('Total generation '+fmt(r.total,2)+' kWh/day',295,262);ctx.fillText('Demand '+fmt(r.load,2)+' kWh/day · balance '+(r.balance>=0?'+':'')+fmt(r.balance,2),295,282);ctx.fillStyle=r.balance>=0?'#4de0ae':'#ff986e';ctx.font='bold 12px system-ui';ctx.fillText(r.balance>=0?'SCENARIO SURPLUS':'SCENARIO DEFICIT',295,307)}
function calculateEnergy(){lastEnergy=null;try{const x=energyInputs(),pv=x.enPV*x.enSun*x.enDerate/100,wind=x.enWind*x.enCF/100*24,hydroPower=9.81*x.enFlow*x.enHead*x.enHydroEta/100,hydro=hydroPower*x.enHydroHours,total=pv+wind+hydro,annual=total*365,loadAnnual=x.enLoad*365,useful=Math.min(annual,loadAnnual),coverage=total/x.enLoad*100,autonomy=x.enBattery/x.enLoad,co2=useful*x.enGridFactor,capex=x.enPV*x.enPvCapex+x.enWind*x.enWindCapex+hydroPower*x.enHydroCapex+x.enBattery*x.enBatteryCapex,savings=useful*x.enTariff,payback=savings>0?capex/savings:Infinity;const r={pv,wind,hydro,hydroPower,total,load:x.enLoad,balance:total-x.enLoad,annual,useful,coverage,autonomy,co2,capex,savings,payback,inputs:x,calcAt:new Date().toISOString()};lastEnergy=r;$('enPVOut').textContent=fmt(pv,2)+' kWh/d';$('enWindOut').textContent=fmt(wind,2)+' kWh/d';$('enHydroOut').textContent=fmt(hydro,3)+' kWh/d';$('enTotalOut').textContent=fmt(total,2)+' kWh/d';$('enCoverage').textContent=fmt(coverage,1)+'%';$('enAutonomy').textContent=fmt(autonomy,2)+' days';$('enUsefulAnnual').textContent=fmt(useful,0)+' kWh/yr';$('enCO2').textContent=fmt(co2,0)+' kg/yr';$('enCapex').textContent='৳'+fmt(capex,0);$('enPayback').textContent=Number.isFinite(payback)?fmt(payback,1)+' years':'Not finite';$('enFormula').textContent='Epv='+fmt(pv,2)+'; Ewind='+fmt(wind,2)+'; Phydro=9.81QHη='+fmt(hydroPower,3)+' kW; Etotal/day='+fmt(total,2)+' kWh; useful annual energy capped at annual load='+fmt(useful,0)+' kWh.';badge('enStatus',total>=x.enLoad?'BALANCE ≥ LOAD':'DEFICIT',''+(total>=x.enLoad?'live':'warn'));status('Scenario recalculated. Resource availability, costs, capacity factor, performance ratio and grid emissions are user inputs. No source-specific Bangladesh market price or audited site yield is implied.','good');drawEnergy(r)}catch(e){badge('enStatus','INVALID INPUT','warn');status('Calculation blocked: '+String(e.message||e),'bad')}}
function initEnergy(){if(!$('page-energyplanner'))return;$('enCalculate')?.addEventListener('click',calculateEnergy);$('enReset')?.addEventListener('click',()=>{const defs={enPV:5,enSun:4.2,enDerate:78,enWind:2,enCF:18,enFlow:.015,enHead:2,enHydroEta:55,enHydroHours:12,enLoad:14,enBattery:12,enGridFactor:.55,enPvCapex:90000,enWindCapex:150000,enHydroCapex:160000,enBatteryCapex:25000,enTariff:8};for(const [id,v] of Object.entries(defs))$(id).value=v;calculateEnergy()});$('enExport')?.addEventListener('click',()=>{calculateEnergy();if(lastEnergy)download('terravex-hybrid-energy-scenario.json',JSON.stringify({...lastEnergy,classification:'engineering estimate; not a commissioned project proposal'},null,2))});energyIds.forEach(id=>$(id)?.addEventListener('change',()=>{badge('enStatus','CHANGES PENDING','sim')}));calculateEnergy()}
