   const heightLimit=x.heightLimit===''||x.heightLimit==null?null:Number(x.heightLimit);
   for(const [v,n] of [[farLimit,'FAR'],[coverageLimit,'coverage limit'],[heightLimit,'height limit']])if(v!==null&&(!Number.isFinite(v)||v<=0))throw new Error(n+' must be blank or a positive value.');
   const areaUnit=x.areaUnit||'m2';if(!AREA[areaUnit])throw new Error('Unsupported area unit.');
   const latRaw=x.latitude??'',lonRaw=x.longitude??'';let latitude=null,longitude=null;if(latRaw!==''||lonRaw!==''){if(latRaw===''||lonRaw==='')throw new Error('Enter both site latitude and longitude, or leave both blank.');latitude=Number(latRaw);longitude=Number(lonRaw);if(!Number.isFinite(latitude)||!Number.isFinite(longitude)||Math.abs(latitude)>90||Math.abs(longitude)>180)throw new Error('Site coordinates must be valid decimal degrees (latitude ±90°, longitude ±180°).');}
   const facadeGross=perimeter*Math.sqrt(coverage/100)*height;
   const multiplier=1+waste/100;
   const finishes=[
     {name:'Floor finish (tile / stone / equivalent)',basis:'Gross floor area × finish allowance',qty:gfa*multiplier},
     {name:'Ceiling finish (non-structural)',basis:'Gross floor area × finish allowance',qty:gfa*multiplier},
     {name:'Roof waterproofing membrane',basis:'Concept footprint × finish allowance',qty:footprint*multiplier},
     {name:'Opaque facade finish / cladding',basis:'Approx. facade envelope × (1 − glazing ratio) × allowance',qty:facadeGross*(1-glazing/100)*multiplier},
     {name:'Glazing surface allowance',basis:'Approx. facade envelope × glazing ratio × allowance',qty:facadeGross*(glazing/100)*(1+waste/100)}
   ];
   const flags=[];
   if(farLimit===null)flags.push({kind:'neutral',title:'FAR not assessed',text:'Enter the verified local FAR limit and applicable use/zone before planning review.'});
   else flags.push(far<=farLimit?{kind:'good',title:'Within entered FAR scenario',text:'Calculated FAR '+FMT(far,2)+' versus user-entered limit '+FMT(farLimit,2)+'. This is not authority approval.'}:{kind:'bad',title:'Above entered FAR scenario',text:'Calculated FAR '+FMT(far,2)+' exceeds the user-entered limit '+FMT(farLimit,2)+'. Revise concept or verify applicable rules.'});
