   ctx.fillStyle='#bce9f7';ctx.font='bold 19px system-ui';ctx.fillText(result.floors+' STOREY CONCEPT',30,42);ctx.fillStyle='#7faec4';ctx.font='12px ui-monospace,monospace';ctx.fillText(result.shape.toUpperCase()+' · '+FMT(result.height,2)+' M · '+FMT(result.gfa,0)+' M² GFA',30,66);ctx.fillText('SCHEMATIC MASSING / NOT A STRUCTURAL MODEL',30,h-24);
