 function dxfSafeText(s){return String(s||'').normalize('NFKD').replace(/[^\x20-\x7E]/g,' ').replace(/[\r\n]+/g,' ').replace(/[^A-Za-z0-9 _.,()/%:+-]/g,'').slice(0,150);}
 function dxfPolyline2d(points,layer,closed=true){let out='0\nPOLYLINE\n8\n'+layer+'\n66\n1\n70\n'+(closed?1:0)+'\n10\n0\n20\n0\n30\n0\n';for(const pt of points)out+='0\nVERTEX\n8\n'+layer+'\n10\n'+pstr(pt[0])+'\n20\n'+pstr(pt[1])+'\n30\n0\n70\n0\n';return out+'0\nSEQEND\n8\n'+layer+'\n';}
 function dxfLine2d(a,b,layer){return '0\nLINE\n8\n'+layer+'\n10\n'+pstr(a[0])+'\n20\n'+pstr(a[1])+'\n30\n0\n11\n'+pstr(b[0])+'\n21\n'+pstr(b[1])+'\n31\n0\n';}
 function dxfText2d(text,x,y,height,layer='TEXT'){return '0\nTEXT\n8\n'+layer+'\n10\n'+pstr(x)+'\n20\n'+pstr(y)+'\n30\n0\n40\n'+pstr(height)+'\n1\n'+dxfSafeText(text)+'\n';}
 function dxfR12Header(minX,minY,maxX,maxY){return '0\nSECTION\n2\nHEADER\n9\n$ACADVER\n1\nAC1009\n9\n$DWGCODEPAGE\n3\nANSI_1252\n9\n$INSBASE\n10\n0\n20\n0\n30\n0\n9\n$EXTMIN\n10\n'+pstr(minX)+'\n20\n'+pstr(minY)+'\n30\n0\n9\n$EXTMAX\n10\n'+pstr(maxX)+'\n20\n'+pstr(maxY)+'\n30\n0\n9\n$LUNITS\n70\n2\n9\n$LUPREC\n70\n4\n9\n$TEXTSTYLE\n7\nSTANDARD\n9\n$CLAYER\n8\n0\n9\n$CELTYPE\n6\nCONTINUOUS\n0\nENDSEC\n';}
 function dxfR12LayerTable(layers){let out='0\nSECTION\n2\nTABLES\n0\nTABLE\n2\nVPORT\n70\n1\n0\nVPORT\n2\n*Active\n70\n0\n10\n0\n20\n0\n11\n1\n21\n1\n12\n0\n22\n0\n13\n0\n23\n0\n14\n0.5\n24\n0.5\n15\n0.5\n25\n0.5\n16\n0\n26\n0\n36\n1\n17\n0\n27\n0\n37\n0\n40\n1000\n41\n1.33\n42\n50\n43\n0\n44\n0\n50\n0\n51\n0\n71\n0\n72\n1000\n73\n1\n74\n3\n75\n0\n76\n0\n77\n0\n78\n0\n0\nENDTAB\n0\nTABLE\n2\nLTYPE\n70\n1\n0\nLTYPE\n2\nCONTINUOUS\n70\n0\n3\nSolid line\n72\n65\n73\n0\n40\n0.0\n0\nENDTAB\n0\nTABLE\n2\nLAYER\n70\n'+layers.length+'\n';for(const [name,color] of layers)out+='0\nLAYER\n2\n'+name+'\n70\n0\n62\n'+color+'\n6\nCONTINUOUS\n';out+='0\nENDTAB\n0\nTABLE\n2\nSTYLE\n70\n1\n0\nSTYLE\n2\nSTANDARD\n70\n0\n40\n0.0\n41\n1.0\n50\n0.0\n71\n0\n42\n2.5\n3\ntxt\n4\n\n0\nENDTAB\n0\nENDSEC\n';return out;}
 function dxfR12Blocks(){return '0\nSECTION\n2\nBLOCKS\n0\nBLOCK\n8\n0\n2\n$Model_Space\n70\n0\n10\n0\n20\n0\n30\n0\n3\n$Model_Space\n1\n\n0\nENDBLK\n8\n0\n0\nBLOCK\n8\n0\n2\n$Paper_Space\n70\n0\n10\n0\n20\n0\n30\n0\n3\n$Paper_Space\n1\n\n0\nENDBLK\n8\n0\n0\nENDSEC\n';}
 function buildPlanDxf(r){
  const L=getPlanLayout(r),layers=[['0',7],['ASSUMED_SITE',8],['FOOTPRINT',4],['ZONE_A',3],['ZONE_B',5],['CORE',6],['CIRCULATION',4],['DIMENSIONS',7],['TEXT',7],['NOTES',1]],minX=L.minX-8,minY=L.minY-10,maxX=L.maxX+12,maxY=L.maxY+10;let out=dxfR12Header(minX,minY,maxX,maxY)+dxfR12LayerTable(layers)+dxfR12Blocks()+'0\nSECTION\n2\nENTITIES\n';
  out+=dxfPolyline2d(L.sitePoints,'ASSUMED_SITE')+dxfPolyline2d(L.footprintPoints,'FOOTPRINT');
  L.zones.forEach((z,i)=>{const layer=z.role==='CORE'?'CORE':i===0?'ZONE_A':'ZONE_B';out+=dxfPolyline2d(z.points,layer)+dxfText2d(z.label,z.centroid[0],z.centroid[1],Math.max(.65,Math.min(1.2,L.w*.018)),'TEXT');});
  for(const pair of L.corridors)out+=dxfLine2d(pair[0],pair[1],'CIRCULATION');
  const dimY=L.minY-3,dimX=L.minX-3;out+=dxfLine2d([L.minX,dimY],[L.maxX,dimY],'DIMENSIONS')+dxfLine2d([dimX,L.minY],[dimX,L.maxY],'DIMENSIONS');out+=dxfText2d('ASSUMED '+r.shape.toUpperCase()+' PARCEL '+FMT(L.plotW,2)+' x '+FMT(L.plotH,2)+' m',(L.minX+L.maxX)/2-4,dimY-1.4,1,'DIMENSIONS');out+=dxfText2d('FOOTPRINT '+FMT(r.footprint,2)+' m2 · '+FMT(r.coverage,1)+'% COVERAGE',L.minX,L.minY-5,1,'DIMENSIONS');out+=dxfText2d('N',L.maxX+2,L.maxY-1,1.8,'TEXT');out+=dxfLine2d([L.maxX+2,L.maxY-5],[L.maxX+2,L.maxY-1.8],'DIMENSIONS');out+=dxfText2d('TERRAVEX '+r.floors+' STOREY '+r.profile.short.toUpperCase()+' '+r.shape.toUpperCase()+' CONCEPT',L.minX,L.maxY+6,1.4,'NOTES');out+=dxfText2d('AUTOCAD 2007 COMPATIBLE R12 / AC1009 · DRAWING UNITS ARE METRES',L.minX,L.maxY+4,1,'NOTES');out+=dxfText2d('NOT FOR CONSTRUCTION · VERIFY SURVEY, ZONING, FIRE, EGRESS, STRUCTURAL AND GEOTECHNICAL DESIGN',L.minX,L.minY-7,.8,'NOTES');out+='0\nENDSEC\n0\nEOF\n';return out;
 }

 function buildSvg(r){return buildPlanSvg(r);}
 function buildHtmlReport(r){
   const d=reportData(r),rows=d.finishAllowances.map(x=>`<tr><td>${escHtml(x.name)}</td><td>${escHtml(x.basis)}</td><td>${FMT(x.qty,2)} m²</td></tr>`).join(''),checks=d.safetyReview.map(x=>`<tr><td>${escHtml(x.label)}</td><td><b>${escHtml(x.status)}</b></td><td>${escHtml(x.detail)}</td></tr>`).join(''),ass=d.assumptions.map(x=>'<li>'+escHtml(x)+'</li>').join(''),refs=['Bangladesh Building Regulatory Authority Act 2026: https://bdlaws.minlaw.gov.bd/act-print-1695.html','BNBC 2020 official gazette: https://www.dpp.gov.bd/bgpress/index.php/document/get_extraordinary/39201','RAJUK planning portal: https://masterplan.rajuk.gov.bd/portal','Copernicus DEM (30 m / 90 m products): https://dataspace.copernicus.eu/explore-data/data-collections/copernicus-contributing-missions/collections-description/COP-DEM','Sentinel-2 resolution guide: https://documentation.dataspace.copernicus.eu/Data/SentinelMissions/Sentinel2.html','ISRIC SoilGrids: https://isric.org/explore/soilgrids','ThinkHazard: https://thinkhazard.org/'];
   return `<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>TERRAVEX Engineering Concept Report</title><style>body{font:14px/1.55 Arial,sans-serif;color:#162e3d;max-width:1100px;margin:32px auto;padding:0 22px}header{border-bottom:3px solid #246a83;padding-bottom:14px}h1,h2{color:#123e54}h2{margin-top:30px}.warning{background:#fff3df;border:1px solid #ddad61;padding:14px;border-radius:8px}table{width:100%;border-collapse:collapse;margin:12px 0}th,td{text-align:left;border-bottom:1px solid #cfdae0;padding:9px;vertical-align:top}th{background:#edf4f7}.kpis{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}.kpis div{padding:12px;background:#eef5f8;border-radius:8px}.kpis b{display:block;font-size:18px;color:#14556c}.actions{position:sticky;top:0;background:white;padding:12px 0;border-bottom:1px solid #ccc}button{padding:10px 16px;border:0;border-radius:6px;background:#12647b;color:white;font-weight:bold;cursor:pointer}@media print{.actions{display:none}body{margin:0;max-width:none}.warning{break-inside:avoid}table{break-inside:auto}tr{break-inside:avoid}}</style><div class="actions"><button onclick="window.print()">Print / Save as PDF</button></div><header><h1>TERRAVEX APEX · Engineering Studio</h1><h2>${escHtml(d.projectTitle)}</h2><p>Generated: ${escHtml(new Date().toLocaleString())}</p><p><b>${escHtml(d.classification)}</b></p></header><div class="warning"><b>ENGINEERING SAFETY NOTICE</b><p>This is a concept-stage planning and non-structural finish allowance report. It is not a construction drawing, permit, tender BOQ, structural safety assessment or professional certification. Do not build from this report.</p></div><h2>1. Project and site summary</h2><div class="kpis"><div>Plot area<b>${FMT(r.plotArea,2)} m²</b></div><div>Footprint<b>${FMT(r.footprint,2)} m²</b></div><div>Gross floor area<b>${FMT(r.gfa,2)} m²</b></div><div>Storeys<b>${r.floors}</b></div><div>Concept height<b>${FMT(r.height,2)} m</b></div><div>FAR scenario<b>${FMT(r.far,3)}</b></div></div><p>Site coordinates: ${d.siteCoordinates?escHtml(FMT(d.siteCoordinates.latitude,6)+', '+FMT(d.siteCoordinates.longitude,6)+' (user-selected 3D Earth view centre; unverified)'):'Not provided'}.</p><h2>2. Satellite / geospatial context</h2><p>${escHtml(d.satelliteContext?.summary||'No satellite metadata query was requested. The assumed parcel is generic and is not derived from satellite measurement.')}</p><p>Catalogue: ${escHtml(d.satelliteContext?.collection||'not queried')} · scene records: ${d.satelliteContext?.sceneCount??'—'} · latest acquisition: ${escHtml(d.satelliteContext?.latestAcquisition||'not available')} · retrieved: ${escHtml(d.satelliteContext?.receivedAt||'not available')}.</p><p>Remote sensing does not establish legal parcel boundaries, terrain survey levels, soil bearing capacity, groundwater, buried utilities or foundation conditions.</p><p>Use: ${escHtml(r.buildingUse)} · Geometry: ${escHtml(r.shape)} · Dimensions: ${FMT(r.dimA,2)} ${escHtml(r.unit)}${r.dimB?' × '+FMT(r.dimB,2)+' '+escHtml(r.unit):''} · Coverage: ${FMT(r.coverage,1)}% · Floor-to-floor: ${FMT(r.floorHeight,2)} m · Finish allowance: ${FMT(r.waste,1)}%.</p><h2>3. Area conversion</h2><table><thead><tr><th>Unit</th><th>Area</th></tr></thead><tbody>${Object.entries(d.plotAreaConversions).map(([u,v])=>`<tr><td>${escHtml(u)}</td><td>${FMT(v,5)}</td></tr>`).join('')}</tbody></table><h2>4. Preliminary finish allowance schedule</h2><table><thead><tr><th>Item</th><th>Basis</th><th>Quantity</th></tr></thead><tbody>${rows}</tbody></table><p>These are preliminary non-structural surface areas only. Excludes structural concrete, reinforcement, structural steel, foundations, beams, columns, MEP, fire systems, stairs/core deductions and procurement wastage optimisation.</p><h2>5. Safety and approval review</h2><table><thead><tr><th>Review area</th><th>Status</th><th>Detail</th></tr></thead><tbody>${checks}</tbody></table><h2>6. Automatic concept program</h2><table><thead><tr><th>Zone</th><th>Share</th><th>Indicative area / floor</th></tr></thead><tbody>${designProgram(r).map(x=>'<tr><td>'+escHtml(x.name)+'</td><td>'+x.sharePercent+'%</td><td>'+FMT(x.indicativeAreaPerFloorM2,2)+' m²</td></tr>').join('')}</tbody></table><ul>${engineeringDescriptions(r).map(x=>'<li><b>'+escHtml(x.title)+':</b> '+escHtml(x.detail)+'</li>').join('')}</ul><h2>7. Calculation assumptions</h2><ul>${ass}</ul><h2>8. Mandatory professional review</h2><ul>${d.professionalReviewRequired.map(x=>'<li>'+escHtml(x)+'</li>').join('')}</ul><h2>9. Excluded scope</h2><ul>${d.excluded.map(x=>'<li>'+escHtml(x)+'</li>').join('')}</ul><h2>10. References to verify</h2><ul>${refs.map(x=>'<li>'+escHtml(x)+'</li>').join('')}</ul><footer><hr><p>Terravex APEX Engineering Studio · Concept report · ${escHtml(r.createdAt)}</p></footer></html>`;
 }

 function render(result){
   latest=result;const unit=result.areaUnit;
   set('engOutPlot',areaFormat(result.plotArea,unit));set('engOutPlotSI',FMT(result.plotArea,2)+' m²');set('engOutFootprint',areaFormat(result.footprint,unit));set('engOutGFA',areaFormat(result.gfa,unit));set('engOutHeight',FMT(result.height,2)+' m');set('engOutFAR',FMT(result.far,3));set('engOutFARState',result.farLimit===null?'Limit not supplied':'Entered limit '+FMT(result.farLimit,2));set('engOutPerimeter',FMT(result.perimeter,2)+' m');set('engVisualShape',result.shape.toUpperCase()+' MASSING');set('engVisualFloors',result.floors+' STOREYS');set('engVisualHeight',FMT(result.height,2)+' M');
   const host=$('engFeasibilityFlags');if(host)host.innerHTML=result.flags.map(f=>'<div class="eng-flag '+f.kind+'"><b>'+escHtml(f.title)+'</b><span>'+escHtml(f.text)+'</span></div>').join('');
   badge('engFeasibilityBadge',result.flags.some(f=>f.kind==='bad')?'SCENARIO LIMIT EXCEEDED':'CONCEPT CHECKED',result.flags.some(f=>f.kind==='bad')?'warn':'sim');
   const body=$('engFinishRows');if(body)body.innerHTML=result.finishes.map(f=>'<tr><td>'+escHtml(f.name)+'</td><td>'+escHtml(f.basis)+'</td><td>'+FMT(f.qty,1)+' m²</td></tr>').join('');
   set('engTimestamp','Calculated '+new Date(result.createdAt).toLocaleString());set('engLiveState','SCENARIO RECALCULATED');const msg=$('engInputMessage');if(msg)msg.textContent='Concept recalculated. Full report, safety review, finish schedule and export options are refreshed above. All quantities are preliminary and non-structural; this is not a construction BOQ or engineering approval.';
   renderReport(result);drawMassing(result);drawFloorPlan(result);if(entered&&$('engAutoRotate')?.checked&&!raf)drawMassing(result,true);
 }
 function clearInvalidOutputs(message){latest=null;if(raf){cancelAnimationFrame(raf);raf=0;}['engOutPlot','engOutPlotSI','engOutFootprint','engOutGFA','engOutHeight','engOutFAR','engOutPerimeter'].forEach(id=>set(id,'—'));set('engVisualShape','INPUT ERROR');set('engVisualFloors','— STOREYS');set('engVisualHeight','— M');const host=$('engFeasibilityFlags');if(host)host.innerHTML='<div class="eng-flag bad"><b>Calculation blocked</b><span>'+escHtml(message)+'</span></div>';const body=$('engFinishRows');if(body)body.innerHTML='<tr><td colspan="3">No schedule generated from invalid input.</td></tr>';badge('engFeasibilityBadge','INPUT ERROR','warn');set('engLiveState','INPUT ERROR');const m=$('engInputMessage');if(m)m.textContent=message;renderReport(null,message);drawMassingError(message);const pc=$('engPlanCanvas');if(pc){const cx=pc.getContext('2d');if(cx){cx.clearRect(0,0,pc.width,pc.height);cx.fillStyle='#f4f8fb';cx.fillRect(0,0,pc.width,pc.height);cx.fillStyle='#a64a42';cx.font='bold 22px system-ui';cx.fillText('2D PLAN PREVIEW UNAVAILABLE',34,70);cx.fillStyle='#587283';cx.font='14px system-ui';cx.fillText(String(message).slice(0,130),34,102);set('engPlanStatus','INPUT ERROR · PREVIEW CLEARED');}}}
 function drawMassingError(message){const c=$('engMassCanvas');if(!c)return;const ctx=c.getContext('2d');if(!ctx)return;ctx.clearRect(0,0,c.width,c.height);ctx.fillStyle='#081827';ctx.fillRect(0,0,c.width,c.height);ctx.fillStyle='#ffb4a8';ctx.font='bold 22px system-ui';ctx.fillText('DESIGN PREVIEW UNAVAILABLE',35,70);ctx.fillStyle='#aac2d2';ctx.font='14px system-ui';ctx.fillText(String(message).slice(0,120),35,105);}
 function calculate(){if(calcTimer){clearTimeout(calcTimer);calcTimer=0;}try{const r=calculateScenario(collect());render(r);return r;}catch(e){clearInvalidOutputs(String(e.message||e));return null;}}
 function pstr(n){return (Math.abs(n)<1e-9?0:n).toFixed(4);}
 function dxfEntityPolyline(points,z,layer){let s='0\nPOLYLINE\n8\n'+layer+'\n66\n1\n70\n9\n10\n0\n20\n0\n30\n0\n';for(const pt of points){s+='0\nVERTEX\n8\n'+layer+'\n10\n'+pstr(pt[0])+'\n20\n'+pstr(pt[1])+'\n30\n'+pstr(z)+'\n70\n32\n';}return s+'0\nSEQEND\n8\n'+layer+'\n';}
 function dxfFace(points,layer){const p=points.length===3?[...points,points[2]]:points;let s='0\n3DFACE\n8\n'+layer+'\n';for(let i=0;i<4;i++)s+=(10+i)+'\n'+pstr(p[i][0])+'\n'+(20+i)+'\n'+pstr(p[i][1])+'\n'+(30+i)+'\n'+pstr(p[i][2])+'\n';return s;}
 function buildDxf(r){const sc=Math.sqrt(r.coverage/100),foot=r.sitePoints.map(p=>[p[0]*sc,p[1]*sc]),z=r.height,minX=Math.min(...r.sitePoints.map(p=>p[0]))-5,minY=Math.min(...r.sitePoints.map(p=>p[1]))-5,maxX=Math.max(...r.sitePoints.map(p=>p[0]))+5,maxY=Math.max(...r.sitePoints.map(p=>p[1]))+5;let out=dxfR12Header(minX,minY,maxX,maxY)+dxfR12LayerTable([['0',7],['SITE',8],['FOOTPRINT',4],['MASSING',5],['LEVELS',3],['NOTES',7]])+dxfR12Blocks()+'0\nSECTION\n2\nENTITIES\n';out+=dxfEntityPolyline(r.sitePoints,0,'SITE')+dxfEntityPolyline(foot,0,'FOOTPRINT');out+=dxfEntityPolyline(foot,z,'MASSING');for(let k=1;k<r.floors;k++)out+=dxfEntityPolyline(foot,z*k/r.floors,'LEVELS');for(let i=0;i<foot.length;i++){const j=(i+1)%foot.length;out+=dxfFace([[foot[i][0],foot[i][1],0],[foot[j][0],foot[j][1],0],[foot[j][0],foot[j][1],z],[foot[i][0],foot[i][1],z]],'MASSING');}for(let i=1;i<foot.length-1;i++)out+=dxfFace([[foot[0][0],foot[0][1],z],[foot[i][0],foot[i][1],z],[foot[i+1][0],foot[i+1][1],z]],'MASSING');out+=dxfText2d('TERRAVEX CONCEPT MASSING - NOT FOR CONSTRUCTION',0,maxY+2,1.5,'NOTES')+dxfText2d('AUTOCAD 2007 COMPATIBLE R12 / AC1009 - DRAWING UNITS ARE METRES',0,maxY+.3,1,'NOTES');out+='0\nENDSEC\n0\nEOF\n';return out;}
 function download(name,data,type){try{const blob=new Blob([data],{type});if(typeof navigator!=='undefined'&&navigator.msSaveBlob){navigator.msSaveBlob(blob,name);return true;}if(typeof URL==='undefined'||typeof URL.createObjectURL!=='function')throw new Error('This browser does not support direct file downloads. Try a current Chrome, Edge or Firefox browser.');const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;a.rel='noopener';a.style.display='none';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),10000);return true;}catch(e){const m=$('engInputMessage');if(m)m.textContent='Export failed: '+String(e.message||e);badge('engReportBadge','EXPORT FAILED','warn');return false;}}
 function exportDxf(){const r=calculate();if(!r)return false;const ok=download('terravex-3d-concept-massing-AutoCAD2007-R12-not-for-construction.dxf',buildDxf(r),'application/dxf');if(ok)set('engInputMessage','3D conceptual massing DXF exported in metres.');return ok;}
 function exportPlanDxf(){const r=calculate();if(!r)return false;const ok=download('terravex-2d-custom-floor-plan-AutoCAD2007-R12-not-for-construction.dxf',buildPlanDxf(r),'application/dxf');if(ok)set('engInputMessage','2D conceptual floor-plan DXF exported in metres. legacy R12 / AC1009 DXF for AutoCAD 2007; selected geometry and typology-specific zones are clipped to the footprint. Drawing units are metres. Concept only.');return ok;}
 function csvEscape(s){return '"'+String(s).replace(/"/g,'""')+'"';}
 function exportCsv(){const r=calculate();if(!r)return false;const rows=[['Item','Basis','Quantity','Unit','Classification'],...r.finishes.map(f=>[f.name,f.basis,FMT(f.qty,3),'m2','Non-structural preliminary allowance'])];const ok=download('terravex-non-structural-finish-allowance.csv','\ufeff'+rows.map(row=>row.map(csvEscape).join(',')).join('\r\n'),'text/csv;charset=utf-8');if(ok)set('engInputMessage','Preliminary non-structural finish allowance CSV exported.');return ok;}
 function exportJson(){const r=calculate();if(!r)return false;const report=reportData(r);const ok=download('terravex-engineering-complete-concept-report.json',JSON.stringify(report,null,2),'application/json');if(ok)set('engInputMessage','Complete concept scenario JSON exported.');return ok;}
 function exportHtml(){const r=calculate();if(!r)return false;const ok=download('terravex-engineering-design-safety-report.html',buildHtmlReport(r),'text/html;charset=utf-8');if(ok)set('engInputMessage','Full HTML engineering report downloaded. Open it in a browser and use Print / Save as PDF.');return ok;}
 function exportSvg(){const r=calculate();if(!r)return false;const ok=download('terravex-concept-site-plan-not-for-construction.svg',buildSvg(r),'image/svg+xml;charset=utf-8');if(ok)set('engInputMessage','2D conceptual plan SVG exported.');return ok;}
 async function useEarthViewCentre(){const mod=window.TERRAVEX_EARTH_COMMAND,C=mod?.getCesium?.(),v=mod?.getViewer?.();if(!C||!v){set('engInputMessage','Open Live 3D Earth, pan/zoom to the proposed project region, return here and press the site-context button again.');badge('engReportBadge','SITE CONTEXT NOT SET','warn');return false;}let cart=null;try{const w=v.canvas?.clientWidth||800,h=v.canvas?.clientHeight||600,pixel=new C.Cartesian2(w/2,h/2),hit=v.camera.pickEllipsoid(pixel,v.scene.globe.ellipsoid);if(hit)cart=C.Cartographic.fromCartesian(hit);else if(v.camera.positionCartographic)cart=v.camera.positionCartographic;}catch{}if(!cart)throw new Error('The centre of the Earth view could not be converted to geographic coordinates. Zoom closer to the land surface and retry.');const lat=C.Math.toDegrees(cart.latitude),lon=C.Math.toDegrees(cart.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180)throw new Error('The selected Earth view centre did not produce valid geographic coordinates.');$('engLatitude').value=String(lat);$('engLongitude').value=String(lon);set('engSatelliteStatus','EARTH VIEW CENTRE SELECTED · '+lat.toFixed(5)+', '+lon.toFixed(5)+' · NOT A SURVEYED PARCEL');if(latest){latest.latitude=lat;latest.longitude=lon;renderReport(latest);}set('engInputMessage','The centre of the existing 3D Earth view is saved as a preliminary map reference. It is not a parcel boundary or survey point. Searching public Sentinel-2 scene metadata…');await loadSatelliteContext(lat,lon);return true;}
 async function loadSatelliteContext(lat,lon){const statusEl=$('engSatelliteStatus'),preview=$('engSatellitePreview');if(statusEl)statusEl.textContent='SEARCHING PUBLIC SENTINEL-2 SCENE CATALOGUE…';if(preview){preview.hidden=true;preview.replaceChildren();}const now=new Date(),start=new Date(now.getTime()-365*86400000),datePart=d=>d.toISOString().slice(0,10);const spanLat=.015,spanLon=.015/Math.max(.2,Math.cos(lat*Math.PI/180)),bbox=[lon-spanLon,lat-spanLat,lon+spanLon,lat+spanLat];const params=new URLSearchParams({collections:'sentinel-2-l2a',bbox:bbox.join(','),datetime:datePart(start)+'T00:00:00Z/'+datePart(now)+'T23:59:59Z',limit:'10',sortby:'-properties.datetime'});try{const controller=new AbortController(),timer=setTimeout(()=>controller.abort(),18000);let response;try{response=await fetch('https://earth-search.aws.element84.com/v1/search?'+params.toString(),{signal:controller.signal,cache:'no-store'});}finally{clearTimeout(timer);}if(!response.ok)throw new Error('STAC catalogue HTTP '+response.status);const data=await response.json(),items=Array.isArray(data.features)?data.features:[];items.sort((a,b)=>Date.parse(b.properties?.datetime||'')-Date.parse(a.properties?.datetime||''));const item=items[0]||null,assets=item?.assets||{},previewUrl=assets.thumbnail?.href||assets.rendered_preview?.href||assets.visual?.href||'';satelliteContext={status:items.length?'CATALOGUE RESULTS':'NO SCENES IN SEARCH WINDOW',summary:items.length?items.length+' Sentinel-2 L2A scene records in a '+(spanLat*2).toFixed(3)+'° query area; latest acquisition '+(item?.properties?.datetime||'timestamp not supplied')+'. Scene metadata is broad context, not parcel identification.':'The public catalogue returned no Sentinel-2 scenes for this query window; no scene or elevation has been inferred.',latitude:lat,longitude:lon,receivedAt:new Date().toISOString(),sceneCount:items.length,latestAcquisition:item?.properties?.datetime||null,cloudCover:item?.properties?.['eo:cloud_cover']??null,collection:'sentinel-2-l2a',previewUrl:previewUrl&&/^https:\/\//i.test(previewUrl)?previewUrl:null};if(statusEl)statusEl.textContent=satelliteContext.status+' · '+items.length+' SCENES · '+(satelliteContext.latestAcquisition||'NO ACQUISITION TIME');if(preview&&item){const title=document.createElement('b');title.textContent='Latest public scene: '+(item.id||'Sentinel-2 L2A');const meta=document.createElement('span');meta.textContent='Acquisition '+(satelliteContext.latestAcquisition||'not supplied')+' · cloud cover '+(satelliteContext.cloudCover===null?'not supplied':Number(satelliteContext.cloudCover).toFixed(1)+'%');preview.append(title,meta);if(satelliteContext.previewUrl){const img=document.createElement('img');img.src=satelliteContext.previewUrl;img.alt='Public Sentinel-2 catalogue preview; not a site survey';img.loading='lazy';img.referrerPolicy='no-referrer';preview.append(img);}preview.hidden=false;}if(latest)renderReport(latest);set('engInputMessage','Satellite metadata search completed. It does not define the legal parcel, plot dimensions, terrain levels, soil or foundation conditions. The auto-generated design assumptions remain clearly labelled.');return satelliteContext;}catch(e){satelliteContext={status:'CATALOGUE UNAVAILABLE',summary:'Public Sentinel-2 catalogue query failed ('+String(e.message||e)+'). No imagery, land cover or elevation result has been fabricated.',latitude:lat,longitude:lon,receivedAt:new Date().toISOString(),sceneCount:0,latestAcquisition:null,cloudCover:null,collection:'sentinel-2-l2a',previewUrl:null};if(statusEl)statusEl.textContent='SATELLITE CATALOGUE UNAVAILABLE · '+String(e.message||e);if(latest)renderReport(latest);set('engInputMessage','Satellite catalogue is unavailable. The conceptual layout can still be downloaded, but the report will identify site imagery as unavailable.');return satelliteContext;}}
 function clearEarthMassing(){const mod=window.TERRAVEX_EARTH_COMMAND,v=mod?.getViewer?.();if(v&&v.entities){for(const entity of earthEntities){try{v.entities.remove(entity)}catch{}}}earthEntities=[];const m=$('engInputMessage');if(m)m.textContent='Terravex concept geometry has been removed from the shared 3D Earth. The Earth imagery and all existing layers are unchanged.';}
 function plotMassingOnEarth(r,lat,lon){const mod=window.TERRAVEX_EARTH_COMMAND,C=mod?.getCesium?.(),v=mod?.getViewer?.();if(!C||!v||!v.entities)throw new Error('The existing Cesium 3D Earth viewer is not ready. Open Live 3D Earth once, then retry.');if(Math.max(r.a||0,r.b||0)>20000)throw new Error('The shared-globe parcel overlay is limited to local concept plots up to 20 km across; use a surveyed GIS polygon for regional projects.');clearEarthMassing();const cosLat=Math.max(.15,Math.cos(lat*Math.PI/180)),toGeo=pt=>[lon+(pt[0]/(111320*cosLat)),lat+(pt[1]/110540)];const plot=r.sitePoints.map(toGeo),scale=Math.sqrt(r.coverage/100),foot=r.sitePoints.map(pt=>toGeo([pt[0]*scale,pt[1]*scale]));const closed=pts=>pts.concat([pts[0]]);const siteLine=closed(plot).flatMap(pt=>pt);const sitePositions=C.Cartesian3.fromDegreesArray(siteLine);const entityStyle=C.Color?.fromCssColorString?C.Color.fromCssColorString('#55d8f4'):C.Color.CYAN;const siteEntity=v.entities.add({name:'TERRAVEX concept parcel boundary (schematic)',polyline:{positions:sitePositions,width:2,material:entityStyle.withAlpha(.85),clampToGround:true}});earthEntities.push(siteEntity);const footprintPositions=C.Cartesian3.fromDegreesArray(foot.flatMap(pt=>pt));const groundHeight=v.scene?.globe?.getHeight?.(C.Cartographic.fromDegrees(lon,lat))||0;const building=v.entities.add({name:'TERRAVEX conceptual building massing — NOT FOR CONSTRUCTION',polygon:{hierarchy:footprintPositions,height:groundHeight,extrudedHeight:groundHeight+r.height,material:entityStyle.withAlpha(.28),outline:true,outlineColor:entityStyle.withAlpha(.95)}});earthEntities.push(building);if(r.floors<=100){for(let k=1;k<r.floors;k++){const z=groundHeight+k*r.floorHeight,level=closed(foot).map(pt=>C.Cartesian3.fromDegrees(pt[0],pt[1],z));const levelEntity=v.entities.add({name:'Concept floor level '+(k+1)+' (visual only)',polyline:{positions:level,width:1,material:entityStyle.withAlpha(.40)}});earthEntities.push(levelEntity);}}const siteDiagonal=Math.hypot(r.a||0,r.b||0);const cameraHeight=Math.min(100000,Math.max(1800,siteDiagonal*2.2+r.height*2.5));v.camera.flyTo({destination:C.Cartesian3.fromDegrees(lon,lat,cameraHeight),duration:1.6});v.scene?.requestRender?.();return earthEntities.length;}
 async function openSiteInEarth(){const r=calculate();if(!r)return;const lat=Number(input('engLatitude')),lon=Number(input('engLongitude'));if(input('engLatitude')===''||input('engLongitude')===''||!Number.isFinite(lat)||!Number.isFinite(lon)||Math.abs(lat)>90||Math.abs(lon)>180){const m=$('engInputMessage');if(m)m.textContent='Enter valid site latitude and longitude first. Coordinates must come from a survey or a user-authorized source; the app does not verify plot boundaries.';return;}document.querySelector('.nav button[data-page=\"earthcommand\"]')?.click();const m=$('engInputMessage');if(m)m.textContent='Opening the shared 3D Earth and preparing the conceptual building overlay…';for(let attempt=0;attempt<32;attempt++){const mod=window.TERRAVEX_EARTH_COMMAND,C=mod?.getCesium?.(),v=mod?.getViewer?.();if(C&&v&&v.entities){try{const n=plotMassingOnEarth(r,lat,lon);if(m)m.textContent='Concept massing plotted on the existing Cesium 3D Earth ('+n+' visual entities). Plot geometry is schematic and coordinates are user-supplied; it is not a surveyed or structural design.';return;}catch(e){if(m)m.textContent=e.message;return;}}await new Promise(resolve=>setTimeout(resolve,250));}if(m)m.textContent='The shared 3D Earth did not become ready. Check the Cesium script/network status, open Live 3D Earth once, then retry.';}

 function enter(){entered=true;updateShapeInputs();if(!latest)calculate();const repaint=()=>{if(!entered)return;if(latest){drawMassing(latest,Boolean($('engAutoRotate')?.checked));drawFloorPlan(latest);renderReport(latest);}};requestAnimationFrame(()=>requestAnimationFrame(repaint));}
 function leave(){entered=false;if(raf){cancelAnimationFrame(raf);raf=0;}if(latest)drawMassing(latest,false);}
 function queueCalculation(){if(calcTimer)clearTimeout(calcTimer);set('engLiveState','CALCULATING FROM INPUTS');badge('engFeasibilityBadge','UPDATING SCENARIO','sim');calcTimer=setTimeout(()=>{calcTimer=0;calculate()},180);}
 function init(){if(!$('page-engineering'))return;['engFloors','engUse','engGeometry','engLayoutStyle'].forEach(id=>$(id)?.addEventListener('input',queueCalculation));['engUse','engGeometry','engLayoutStyle'].forEach(id=>$(id)?.addEventListener('change',()=>{updateShapeInputs();queueCalculation();}));$('engUseEarthContext')?.addEventListener('click',()=>useEarthViewCentre().catch(e=>set('engSatelliteStatus','SITE CONTEXT FAILED · '+String(e.message||e))));$('engRenderMode')?.addEventListener('change',()=>{if(latest)drawMassing(latest)});$('engAutoRotate')?.addEventListener('change',()=>{if(!$('engAutoRotate').checked&&raf){cancelAnimationFrame(raf);raf=0;}else if(latest&&!raf)drawMassing(latest,true)});$('engViewReset')?.addEventListener('click',()=>{angle=0;if(latest){drawMassing(latest);if(entered&&$('engAutoRotate')?.checked)drawMassing(latest,true);}});$('engCalculate')?.addEventListener('click',calculate);$('engGeometry')?.addEventListener('change',updateShapeInputs);$('engRunScenario')?.addEventListener('click',calculate);$('engReset')?.addEventListener('click',()=>{if($('engFloors'))$('engFloors').value='8';if($('engUse'))$('engUse').value='residential';if($('engGeometry'))$('engGeometry').value='rectangle';if($('engLayoutStyle'))$('engLayoutStyle').value='auto';if($('engLatitude'))$('engLatitude').value='';if($('engLongitude'))$('engLongitude').value='';satelliteContext=null;const preview=$('engSatellitePreview');if(preview){preview.replaceChildren();preview.hidden=true;}set('engSatelliteStatus','SITE NOT SELECTED · GENERIC LAND ASSUMPTIONS ONLY');calculate()});$('engExportPlanDxf')?.addEventListener('click',exportPlanDxf);$('engQuickExportPlanDxf')?.addEventListener('click',exportPlanDxf);$('engExportDxf')?.addEventListener('click',exportDxf);$('engQuickExportDxf')?.addEventListener('click',exportDxf);$('engExportCsv')?.addEventListener('click',exportCsv);$('engQuickExportCsv')?.addEventListener('click',exportCsv);$('engExportJson')?.addEventListener('click',exportJson);$('engQuickExportJson')?.addEventListener('click',exportJson);$('engExportReport')?.addEventListener('click',exportHtml);$('engQuickExportHtml')?.addEventListener('click',exportHtml);$('engQuickExportSvg')?.addEventListener('click',exportSvg);$('engOpenEarth')?.addEventListener('click',openSiteInEarth);$('engClearEarth')?.addEventListener('click',clearEarthMassing);$('engGenerateReport')?.addEventListener('click',()=>{$('engReportMonitor')?.scrollIntoView({behavior:'smooth',block:'start'});if(latest)renderReport(latest);});calculate();}
 window.TERRAVEX_ENGINEERING_STUDIO={enter,leave,calculate,calculateScenario,buildDxf,buildPlanDxf,buildSvg,buildHtmlReport,reportData,safetyReview,designProgram,makeAutoAssumptions,getPlanLayout,drawFloorPlan,drawMassing,plotMassingOnEarth,clearEarthMassing,useEarthViewCentre,getLatest:()=>latest,getSatelliteContext:()=>satelliteContext};
 if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',init,{once:true});else init();
